dtsPropsFor.Btn:
/** Visual weight: primary = filled amber key, ghost = hairline, danger = red outline. */
variant?: "primary" | "ghost" | "danger";
children?: React.ReactNode;
onClick?: React.MouseEventHandler<HTMLButtonElement>;
disabled?: boolean;
type?: "button" | "submit" | "reset";
title?: string;
className?: string;
style?: React.CSSProperties;

dtsPropsFor.Delta:
/** Signed value; null renders the flat placeholder. */
v: number | null;
/** Text size of the readout. */
size?: "sm" | "lg";
/** Placeholder shown when v is null (default "—"). */
nullText?: string;

dtsPropsFor.Field:
/** Micro-label shown above the control. */
label: string;
/** The form control this label wraps. */
children: React.ReactNode;

dtsPropsFor.Sel:
/** Current selected value. */
value: string;
/** Fired with the new value on change. */
onChange: (v: string) => void;
/** Selectable options. */
options: { value: string; label: string }[];
/** Accessible label (the select has no visible <label>). */
ariaLabel?: string;
className?: string;

dtsPropsFor.Modal:
/** Amber header title. */
title: string;
/** Called on overlay click, close button, or Escape. */
onClose: () => void;
/** Dialog body. */
children: React.ReactNode;
/** Widen the dialog (max-w-lg vs the default max-w-md). */
wide?: boolean;

dtsPropsFor.Panel:
/** Optional amber header-strip label. Omit for a bare bordered panel. */
title?: string;
/** Content rendered on the right side of the header. */
right?: React.ReactNode;
/** Panel body. */
children: React.ReactNode;
/** Pad the body (default true). */
pad?: boolean;
className?: string;

dtsPropsFor.SortHeader:
/** Column label text. */
label: string;
/** Key this column sorts by. */
sortKey: string;
/** Current sort state. */
sort: { key: string; dir: "asc" | "desc" };
/** Called with the column key when the header is clicked. */
onSort: (key: string) => void;
/** Text alignment (default "right"). */
align?: "left" | "right";

dtsPropsFor.Sparkline:
/** Score series; the last 14 are drawn. Needs at least 2 points, else it renders a "needs 2+ results" stub. */
scores: number[];
/** Stroke/fill color (usually the subject color). */
color: string;
/** SVG width in px (default 132). */
w?: number;
/** SVG height in px (default 38). */
h?: number;
/** Optional per-point captions (dates, titles) shown in the hover readout. */
labels?: string[];

dtsPropsFor.Toggle:
/** On/off state — renders [■] when on, [ ] when off. */
on: boolean;
/** Toggle handler. */
onClick: () => void;
/** Label after the checkbox glyph. */
children: React.ReactNode;

dtsPropsFor.RatingBadge:
/** Sell-side consensus call. Colors ride the gain/loss axis; HOLD stays grey and "N/A" recedes to a faint hairline. */
rating: "STRONG BUY" | "BUY" | "HOLD" | "SELL" | "STRONG SELL" | "N/A";
/** Use the abbreviated label ("STR BUY") for the tape and tight table cells. */
short?: boolean;
/** Chip size (default "sm"). */
size?: "sm" | "lg";

dtsPropsFor.RegimeTag:
/** Risk regime; PRIME is green, STABLE grey, STRESSED amber, DISTRESSED red. */
regime: "PRIME" | "STABLE" | "STRESSED" | "DISTRESSED";
/** Chip size (default "sm"). */
size?: "sm" | "lg";

dtsPropsFor.DelistedTag:
/** ISO date the desk closed; when set, the stamp reads "DELISTED <date>" and carries a tooltip. */
closedAt?: string | null;
/** Chip size (default "sm"). */
size?: "sm" | "lg";
